const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db={materials:[],questions:[],sessions:[],subjects:[]},page='home',session=null;
try{db=JSON.parse(localStorage.getItem('lockin-v1'))||db}catch{}
db.subjects ||= [];
function save(){try{localStorage.setItem('lockin-v1',JSON.stringify(db))}catch{toast('Storage is full. Export a backup before closing.')}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}
const uid=()=>crypto.randomUUID();
function heading(k,t,d,action=''){return `<div class="heading"><div><span class="kicker">${k}</span><h1>${t}</h1><p>${d}</p></div>${action}</div>`}
function go(p){page=p;session=null;render();window.scrollTo(0,0)}
function materialCard(m){return `<article class="card"><span class="file-icon">▤</span><h3>${esc(m.title)}</h3><p>${esc(m.subject||'Unsorted')} · ${esc(m.type)} · ${new Date(m.date).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</p><span class="pill">${db.questions.filter(q=>q.material===m.id).length} questions</span><div class="card-actions"><button class="primary" data-study="${m.id}">Practice →</button><button data-generate="${m.id}">Generate</button><button class="danger" data-delete="${m.id}" aria-label="Delete ${esc(m.title)}">×</button></div></article>`}
function render(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#breadcrumb').textContent='Workspace / '+({home:'Overview',library:'My materials',bank:'Question bank',practice:'Practice'}[page]);let html='';
if(page==='home'){let total=db.sessions.reduce((n,s)=>n+s.total,0),correct=db.sessions.reduce((n,s)=>n+s.correct,0);html=heading('','Study','Your subjects, materials, and practice sessions.','<button class="primary" data-import>＋ Add material</button>')+`<div class="stats"><div class="stat"><span>▤ &nbsp; Study materials</span><strong>${db.materials.length}</strong></div><div class="stat"><span>▦ &nbsp; Practice questions</span><strong>${db.questions.length}</strong></div><div class="stat"><span>↗ &nbsp; Self-rated recall</span><strong>${total?Math.round(correct/total*100)+'%':'—'}</strong></div></div><div class="section-head"><h2>Your study shelf</h2><button class="text-button" data-page="library">View all materials →</button></div>${db.materials.length?'<div class="cards">'+db.materials.slice(-3).reverse().map(materialCard).join('')+'</div>':'<div class="empty"><h3>A fresh start, all yours.</h3><p>Add your first set of notes or try a sample to explore.</p><button class="primary" data-import>Add material</button> <button id="sample">Try sample material</button></div>'}`}
if(page==='library')html=heading('','My materials','Your notes, quizzes, and practice tests in one place.','<button class="primary" data-import>＋ Add material</button>')+`<div class="notice">Files and progress stay in this browser. Export a backup to move them to another device. Word, PDF, and photo extraction require an internet connection. Review extracted text before saving.</div><div class="toolbar"><input type="search" id="materialSearch" placeholder="Search materials…"><select id="subjectFilter"><option value="">All subjects</option>${db.subjects.map(x=>`<option>${esc(x)}</option>`).join('')}</select><button id="newSubject">＋ New subject</button><button id="restore">Restore backup</button><input id="restoreFile" type="file" accept=".json" hidden></div><div class="cards" id="materialCards">${db.materials.map(materialCard).join('')||'<div class="empty">Your library is ready for its first material.</div>'}</div>`;
if(page==='bank')html=heading('','Question bank','Review imported answers and questions generated from your notes.')+`<div class="notice">Questions are reviewed before saving. Formula application problems use recognized equations; unknown formulas need your answer. Older generated questions remain until you delete them.</div><div class="toolbar"><input type="search" id="questionSearch" placeholder="Find a question…"><select id="bankFilter"><option value="">All materials</option>${options()}</select></div><div id="questionRows">${questionRows(db.questions)}</div>`;
if(page==='practice')html=heading('','Practice','Choose material and a session type.')+`<section class="quiz setup"><span class="kicker">BUILD YOUR SESSION</span><h2>What are we studying?</h2><label>Study material<select id="studyMaterial"><option value="">All materials</option>${options()}</select></label><label>Session style<select id="studyMode"><option value="quiz">Practice quiz — write, reveal, self-rate</option><option value="flash">Flashcards — flip and self-rate</option></select></label><label>Number of questions<select id="studyCount"><option>5</option><option selected>10</option><option>20</option><option>50</option></select></label><label><span><input type="checkbox" id="missed"> Focus on questions marked “Need practice”</span></label><p>Answers are self-rated, so you can judge meaning in your own words.</p><button class="primary" id="start">Start session →</button>${!db.questions.length?'<p>Add material and generate questions first, or try the sample on Overview.</p>':''}</section>`;
$('#view').innerHTML=html;bind()}
function options(){return db.materials.map(m=>`<option value="${m.id}">${esc(m.title)}</option>`).join('')}
function questionRows(qs){return qs.map(q=>`<details class="question-row"><summary>${esc(q.question)}</summary><button class="text-button danger" data-remove-question="${q.id}">Delete question</button><p>${esc(q.answer)}</p><div class="source">${esc(db.materials.find(m=>m.id===q.material)?.title||'Material')} · ${esc(q.kind|| (q.generated?'Legacy generated question':'Imported question'))}${q.missed?' · Needs practice':''}</div></details>`).join('')||'<div class="empty">No questions here yet. Generate from a material in your library.</div>'}
function bind(){document.querySelectorAll('[data-remove-question]').forEach(b=>b.onclick=()=>{if(confirm('Delete this question?')){db.questions=db.questions.filter(q=>q.id!==b.dataset.removeQuestion);save();render()}});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));document.querySelectorAll('[data-import]').forEach(b=>b.onclick=openImport);document.querySelectorAll('[data-generate]').forEach(b=>b.onclick=()=>generate(b.dataset.generate));document.querySelectorAll('[data-study]').forEach(b=>b.onclick=()=>{go('practice');$('#studyMaterial').value=b.dataset.study});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('Delete this material and its questions?')){db.materials=db.materials.filter(m=>m.id!==b.dataset.delete);db.questions=db.questions.filter(q=>q.material!==b.dataset.delete);save();render()}});if($('#sample'))$('#sample').onclick=sample;if($('#start'))$('#start').onclick=start;if($('#materialSearch'))$('#materialSearch').oninput=e=>{$('#materialCards').innerHTML=db.materials.filter(m=>m.title.toLowerCase().includes(e.target.value.toLowerCase())).map(materialCard).join('');bindCards()};if($('#questionSearch')){let filter=()=>$('#questionRows').innerHTML=questionRows(db.questions.filter(q=>(!$('#bankFilter').value||q.material===$('#bankFilter').value)&&q.question.toLowerCase().includes($('#questionSearch').value.toLowerCase())));const applyFilter=()=>{filter();document.querySelectorAll('[data-remove-question]').forEach(b=>b.onclick=()=>{if(confirm('Delete this question?')){db.questions=db.questions.filter(q=>q.id!==b.dataset.removeQuestion);save();applyFilter()}})};$('#questionSearch').oninput=applyFilter;$('#bankFilter').onchange=applyFilter}if($('#newSubject'))$('#newSubject').onclick=addSubject;if($('#subjectFilter'))$('#subjectFilter').onchange=()=>{const sub=$('#subjectFilter').value;$('#materialCards').innerHTML=db.materials.filter(m=>!sub||m.subject===sub).map(materialCard).join('');bindCards()};if($('#restore')){$('#restore').onclick=()=>$('#restoreFile').click();$('#restoreFile').onchange=restore}}
function bindCards(){document.querySelectorAll('[data-study]').forEach(b=>b.onclick=()=>{go('practice');$('#studyMaterial').value=b.dataset.study});document.querySelectorAll('[data-generate]').forEach(b=>b.onclick=()=>generate(b.dataset.generate));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('Delete this material and its questions?')){db.materials=db.materials.filter(m=>m.id!==b.dataset.delete);db.questions=db.questions.filter(q=>q.material!==b.dataset.delete);save();render()}})}
function subjectOptions(){return '<option value="">Unsorted</option>'+db.subjects.map(x=>'<option value="'+esc(x)+'">'+esc(x)+'</option>').join('')}
function addSubject(){let name=prompt('Name your subject (e.g. Biology, History, Calculus)');if(!name?.trim())return;name=name.trim().slice(0,100);if(!db.subjects.includes(name))db.subjects.push(name);save();if(document.querySelector('#subject'))document.querySelector('#subject').innerHTML=subjectOptions();render()}
function openImport(){$('#importForm').reset();delete $('#materialText').dataset.type;$('#subject').innerHTML=subjectOptions();$('#importError').textContent='';$('#importDialog').showModal()}
$('#closeDialog').onclick=()=>$('#importDialog').close();
async function loadScript(url,key){if(window[key])return window[key];await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=url;script.onload=resolve;script.onerror=()=>reject(Error('Could not load the file reader. Check your internet connection.'));document.head.appendChild(script)});return window[key]}
async function ocr(image){const lib=await loadScript('https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js','Tesseract');const worker=await lib.createWorker('eng');try{return (await worker.recognize(image)).data.text}finally{await worker.terminate()}}
$('#file').onchange=async()=>{const f=$('#file').files[0];if(!f)return;if(!$('#materialTitle').value)$('#materialTitle').value=f.name.replace(/\.[^.]+$/,'');const submit=$('#importForm button[type=submit]');submit.disabled=true;$('#importError').textContent='Extracting text… Large scans can take a few minutes.';try{if(f.size>10*1024*1024)throw Error('Use a file smaller than 10 MB.');const ext=f.name.split('.').pop().toLowerCase();let text;if(ext==='pdf')text=await pdfText(f);else if(ext==='docx'){let lib=await loadScript('https://cdn.jsdelivr.net/npm/mammoth@1.8.0/mammoth.browser.min.js','mammoth');text=(await lib.extractRawText({arrayBuffer:await f.arrayBuffer()})).value}else if(['png','jpg','jpeg','webp'].includes(ext))text=await ocr(f);else if(['txt','csv','json'].includes(ext))text=await f.text();else throw Error('Use PDF, DOCX, PNG, JPG, WEBP, TXT, CSV or JSON. Older .doc files must be saved as .docx.');if(!text.trim())throw Error('No readable text found. Try a clearer image or paste the text.');$('#materialText').value=text;$('#materialText').dataset.type=['csv','json'].includes(ext)?ext:'notes';$('#importError').textContent='Text extracted. Review and correct it below before adding.'}catch(err){$('#importError').textContent=err.message;$('#materialText').value=''}finally{$('#file').value='';submit.disabled=false}};

function csv(text){let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if(c==='\n'&&!quoted){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('CSV has an unclosed quote.');if(cell||row.length){row.push(cell.replace(/\r$/,''));rows.push(row)}return rows}
function parseQuestions(text,type){if(type==='json'){const a=JSON.parse(text);if(!Array.isArray(a))throw Error('JSON must be an array of question/answer objects.');if(!a.every(q=>q&&typeof q.question==='string'&&typeof q.answer==='string'&&q.question.trim()&&q.answer.trim()))throw Error('Each JSON question needs a nonempty question and answer.');return a.map(q=>({question:q.question.trim(),answer:q.answer.trim()}))}if(type==='csv'){let rows=csv(text.replace(/^\uFEFF/,'')),head=rows.shift().map(s=>s.trim().toLowerCase()),qi=head.indexOf('question'),ai=head.indexOf('answer');if(qi<0||ai<0)throw Error('CSV needs question and answer headers.');return rows.filter(r=>r.some(s=>s.trim())).map(r=>{if(!r[qi]?.trim()||!r[ai]?.trim())throw Error('Every CSV row needs a question and answer.');return{question:r[qi].trim(),answer:r[ai].trim()}})}return [...text.matchAll(/(?:^|\n)Q:\s*([^\n]+)\nA:\s*([^\n]+)/gi)].map(m=>({question:m[1].trim(),answer:m[2].trim()}))}
async function pdfText(file){const lib=await import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs');lib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs';let doc=await lib.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;try{let out=[];for(let i=1;i<=doc.numPages;i++){const content=await(await doc.getPage(i)).getTextContent();let text=content.items.map(x=>x.str+(x.hasEOL?'\n':' ')).join('');if(text.trim().length<30){const page=await doc.getPage(i),viewport=page.getViewport({scale:1.5}),canvas=document.createElement('canvas');canvas.width=viewport.width;canvas.height=viewport.height;await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;text=await ocr(canvas)}out.push(text)}return out.join('\n')}finally{await doc.destroy()}}
$('#importForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;button.textContent='Reading material…';try{const file=$('#file').files[0];if(file&&file.size>10*1024*1024)throw Error('Please use a file smaller than 10 MB.');let type=file?file.name.split('.').pop().toLowerCase():($('#materialText').dataset.type||'notes');if(file&&!['txt','csv','json','pdf'].includes(type))throw Error('Use TXT, CSV, JSON or a text-based PDF.');let text=file?(type==='pdf'?await pdfText(file):await file.text()):$('#materialText').value; if(file&&$('#materialText').value.trim())text+='\n'+$('#materialText').value;if(!text.trim())throw Error('No readable text found. Paste notes or use a PDF with selectable text.');const qs=['csv','json'].includes(type)?parseQuestions(text,type):null,m={id:uid(),title:$('#materialTitle').value.trim(),text,type:type.toUpperCase(),subject:$('#subject').value,date:Date.now()};reviewMaterial(m,qs)}catch(err){$('#importError').textContent=err.message||'Could not read that file.'}finally{button.disabled=false;button.textContent='Review detected items →'}};
function generate(id){reviewMaterial(db.materials.find(m=>m.id===id))}
function sample(){let m={id:uid(),title:'The science of learning',type:'SAMPLE NOTES',date:Date.now(),text:'Active recall strengthens memory by retrieving information without looking at notes.\nSpaced repetition involves reviewing information at increasing intervals over time.\nInterleaving means mixing different topics during a practice session.\nSleep supports the consolidation of newly learned information into long-term memory.'};db.materials.push(m);db.questions.push(...[{question:'What is active recall?',answer:'Retrieving information without looking at notes.'},{question:'What is spaced repetition?',answer:'Reviewing information at increasing intervals over time.'},{question:'What is interleaving?',answer:'Mixing different topics during a practice session.'},{question:'How does sleep support learning?',answer:'It supports consolidation into long-term memory.'}].map(q=>({...q,id:uid(),material:m.id,kind:'question'})));save();render();toast('Sample added.')}
function start(){let qs=db.questions.filter(q=>(!$('#studyMaterial').value||q.material===$('#studyMaterial').value)&&(!$('#missed').checked||q.missed));for(let i=qs.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[qs[i],qs[j]]=[qs[j],qs[i]]}qs=qs.slice(0,Number($('#studyCount').value));if(!qs.length)return toast('No matching questions. Generate questions from your materials first.');session={qs,index:0,correct:0,mode:$('#studyMode').value,revealed:false};showQuestion()}
function showQuestion(){const s=session,q=s.qs[s.index];$('#view').innerHTML=`<section class="quiz"><div class="section-head"><span class="kicker">${s.mode==='flash'?'FLASHCARDS':'PRACTICE QUIZ'} · ${s.index+1} OF ${s.qs.length}</span><button class="text-button" id="quit">End session</button></div><div class="progress"><div style="width:${s.index/s.qs.length*100}%"></div></div><div class="${s.mode==='flash'?'flash':''}" id="questionFace"><h2>${esc(q.question)}</h2>${s.mode==='flash'?'<p>Think of your answer, then reveal.</p>':''}</div>${s.mode==='quiz'?'<label>Your answer<textarea rows="4" placeholder="Try recalling it in your own words…"></textarea></label>':''}<div id="revealArea"><button class="primary" id="reveal">Reveal answer ${s.mode==='flash'?'↻':'→'}</button></div></section>`;$('#quit').onclick=()=>{if(confirm('End this session? Unfinished results will not be saved.'))go('practice')};$('#reveal').onclick=reveal}
function reveal(){let s=session,q=s.qs[s.index];s.revealed=true;$('#revealArea').innerHTML=`<div class="answer"><span class="kicker">REFERENCE ANSWER</span><p>${esc(q.answer)}</p></div><p>How did you do? Compare your answer, then rate your recall.</p><div class="quiz-actions"><button class="secondary" id="again">Need practice</button><button class="primary" id="got">Got it ✓</button></div>`;$('#again').onclick=()=>rate(false);$('#got').onclick=()=>rate(true)}
function rate(correct){let s=session,q=s.qs[s.index];q.missed=!correct;if(correct)s.correct++;s.index++;save();if(s.index<s.qs.length)return showQuestion();db.sessions.push({id:uid(),date:Date.now(),correct:s.correct,total:s.qs.length});save();$('#view').innerHTML=`<section class="quiz" style="text-align:center"><span class="kicker">SESSION COMPLETE</span><h1>That's progress.</h1><h2>${s.correct} / ${s.qs.length} recalled</h2><p>Every attempt makes the next one easier. Revisit the questions marked “Need practice” in your next session.</p><button class="primary" data-page="practice">Study again →</button> <button data-page="home">Back to overview</button></section>`;bind();session=null}
$('#backup').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({version:1,...db},null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download='lock-in-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
async function restore(e){try{let f=e.target.files[0];if(!f)return;if(f.size>25*1024*1024)throw Error('Backup is too large.');let d=JSON.parse(await f.text());if(d.version!==1||!Array.isArray(d.materials)||!Array.isArray(d.questions)||!Array.isArray(d.sessions)||!d.materials.every(m=>typeof m.id==='string'&&typeof m.title==='string'&&typeof m.text==='string'&&typeof m.type==='string'&&Number.isFinite(m.date))||!d.questions.every(q=>typeof q.id==='string'&&typeof q.question==='string'&&typeof q.answer==='string'&&d.materials.some(m=>m.id===q.material))||!d.sessions.every(s=>Number.isFinite(s.date)&&Number.isFinite(s.total)&&Number.isFinite(s.correct)&&s.correct>=0&&s.correct<=s.total))throw Error('This is not a valid Lock In backup.');if(!confirm('Replace this browser’s library and progress with the backup?'))return;db={materials:d.materials,questions:d.questions,sessions:d.sessions,subjects:Array.isArray(d.subjects)?d.subjects.filter(x=>typeof x==='string'):[]};save();render();toast('Backup restored.')}catch(err){toast(err.message)}}
render();

$('#createSubject').onclick=()=>{addSubject();$('#subject').value=db.subjects.at(-1)||''};
